import{_ as e,H as n,f as r,i as a}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"直播加餐｜揭秘Transformer技术内幕","description":"","frontmatter":{},"headers":[{"level":2,"title":"注意力（Attention）机制","slug":"注意力-attention-机制","link":"#注意力-attention-机制","children":[]},{"level":2,"title":"Transformer 的整体结构","slug":"transformer-的整体结构","link":"#transformer-的整体结构","children":[]}],"relativePath":"编程高手必学的内存知识/直播加餐｜揭秘Transformer技术内幕.md","filePath":"编程高手必学的内存知识/直播加餐｜揭秘Transformer技术内幕.md","lastUpdated":1779821602000}'),o={name:"编程高手必学的内存知识/直播加餐｜揭秘Transformer技术内幕.md"};function s(p,t,i,A,f,E){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="直播加餐-揭秘transformer技术内幕" tabindex="-1">直播加餐｜揭秘Transformer技术内幕 <a class="header-anchor" href="#直播加餐-揭秘transformer技术内幕" aria-label="Permalink to &quot;直播加餐｜揭秘Transformer技术内幕&quot;">​</a></h1><p>欢迎大家来到这次直播，周末愉快！首先我们回顾一下，上次直播我们介绍了 AI Infra 的相关知识。其中第三部分关于 Transformer 的结构没有展开，今天我们就来完成这部分内容。</p><p>接下来我先介绍一下自己。我叫海纳，目前是摩尔线程编译器团队的负责人。我之前参与过华为 JDK 的研发，以及静态编译器、推理引擎等开发工作。在极客专栏上，我撰写了《编程高手必学的内存知识》《从零开始写 Python 虚拟机》等专栏，也出版了《从零开始写 Linux 内核》等图书。关于这些专栏和图书，我会在直播接近结束时再作介绍。</p><p>上次直播我们讨论了一个问题：传统 Infra 与当前 AI Infra 之间究竟有哪些区别？实际上，可能有人会认为，我以前写的专栏、写的 Linux 内核——尤其是那个 35 年前的内核版本——会不会过于陈旧？这些知识是否已经过时？但我们上节课恰恰回答了这个问题：无论形式如何变化，其内在的知识体系并没有发生根本性的改变。</p><p>上节课我们重点讲解了 GPU 的体系结构。我们从多核 CPU 的并发讲起，一直延伸到 GPU 如何将这些概念硬件化。这部分内容不再重复，如果当时没来得及看或仍有疑问，可以回看上一期的直播回放，也欢迎随时交流。</p><p>我们还对比了传统 Infra 与 AI Infra，涉及操作系统的驱动、编译器等内容。以前的编译器主要基于 GCC、LLVM 进行静态编译，目标平台集中在 x86、Arm 等架构。而在 GPU 与 AI 时代，编译器的能力依然存在，且覆盖场景更加广泛，例如虚拟指令集、推理引擎、算子自动生成、图算融合优化等。这些本质上仍属于编译器的范畴——形式虽变，核心未改。</p><p>体系结构方面也是如此。上世纪90年代研究的指令级并行、流水线、I/O 端口、存储体系等问题，至今仍在研究。只不过随着制程进步，频率从几百兆提升到更高，功耗控制、FLOPS（每秒浮点运算次数）也从几兆发展到几 T 甚至接近 P 级。虽然实现了成千上万倍的提升，但领域内讨论的问题依然是那些，只不过时间尺度从毫秒级进入了纳秒级。</p><p>算法与数据结构同样没有发生太大变化。以往研究的树、图等结构，在 GPU 时代仍然适用。上节课已经讨论过，这里快速回顾一下。</p><p>今天我们将聚焦于深度神经网络中的 Transformer 模型。近十年来，Transformer 这个词反复出现，它的问世极大推动了自然语言处理的发展。那么 Transformer 是如何工作的？它的模型结构是怎样的？</p><p>实际上，Transformer 源自 2017 年的论文《Attention Is All You Need》。正是这篇文章推动了大模型向这个方向发展。所谓“大模型”，正是因为 Transformer 结构需要足够参数量才能展现出强大的能力——只有当参数规模达到一定程度，才会涌现出出色的自然语言处理性能。</p><p>要理解 Transformer，通常需要从词嵌入、RNN 等前置知识入手，阅读量大且不易实践验证。今天我将换一种方式讲解：不追求严谨定义，而是通过易于理解的例子帮助大家直观感受。请注意，今天所讲的内容并不完全精确，但能帮助你形成直观理解。如需准确的理论，还请阅读论文、查阅资料进行深入学习。</p><h2 id="注意力-attention-机制" tabindex="-1"><strong>注意力（Attention）机制</strong> <a class="header-anchor" href="#注意力-attention-机制" aria-label="Permalink to &quot;**注意力（Attention）机制**&quot;">​</a></h2><p>理解 Transformer 的关键在于其中的注意力（Attention）机制。我们通过一个例子来说明：假设你要给一家餐厅打分，怎么打才合理？显然，分数并不笼统，而是取决于菜单。比如，喜欢吃海鲜的人可能给海鲜馆高分，喜欢辣味的人可能给川菜馆高分。如果你没吃过，打分就不客观；即使吃过，但如果只尝了菜单上的 8-10 道菜，评分依然可能片面。</p><p>这种“主观性”其实就是注意力。你去一家餐厅，不是因为它的名字，而是因为有你喜欢吃的菜——这些菜也不一定是招牌菜，因为个人口味未必与招牌匹配。这一点应该容易理解。</p><p>我们以四道菜为例，先给出一个相对客观的评价表。比如石斑鱼，新鲜度 0.8，辣度 0.2；小炒肉，香气 0.8，辣度 0.8；等等。注意，这张表目前是客观的，不涉及个人喜好。我们稍后会为它命名。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/a953eb4628924a4a0c27636760yyb65e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/a953eb4628924a4a0c27636760yyb65e.png" alt="图片"></a></p><p>接下来，三位客人进入餐厅：广东人、山东人、四川人。他们各有喜好：广东人海鲜需求为 0，但注重新鲜度与色泽；山东人口味均衡；四川人则偏爱辣味，辣度权重设为 1.0。这些只是个人口味倾向。</p><p>那么，他们如何给餐厅打分？第一步不是直接评分，而是点菜——点菜时就已经体现出倾向性。例如，四川人可能不会点银鱼炒蛋或石斑鱼，而更可能点水煮鱼和小炒肉；广东人可能不喜欢辣，甚至可将辣度权重设为负值。第一步要计算的是每个人点每道菜的概率。</p><p>这其实很简单：将个人喜好向量与每道菜的客观向量做内积，即可反映点菜的可能性。有线性代数背景的同学很容易理解：向量化后做内积，就能看出点菜顺序。例如，广东人最可能点银鱼炒蛋，其次是石斑鱼；四川人则明显更倾向水煮鱼和小炒肉。</p><p>这样，我们就得到了一个概率矩阵：每个人点每道菜的可能性。也就是说，广东人给餐厅打分，主要看石斑鱼和银鱼炒蛋做得好不好；小炒肉再难吃，他也不太会点，所以对评分影响小。反之，四川人若觉得水煮鱼和小炒肉好吃，即使石斑鱼不新鲜，也可能给高分。到这一步，应该没有问题。</p><p>但这个权重矩阵尚未归一化。例如四川人点水煮鱼的值为 1.7，小炒肉为 1.6，加总后与山东人的总值不同。山东人口味均衡，点菜概率分布较平均，但数值上仍显散碎，无法直接比较。既然我们谈论概率，就希望每一行之和为 1，这样才能进行跨行比较。</p><p>最简单的归一化是将每行求和，再以各元素除以该和。但这种做法在神经网络中有缺点：一是容易导致分布陡峭，二是不利于求导。神经网络训练需要求导，而像 x 分之一这样的函数求导并不方便。我们更倾向于使用 exp 函数，因为它求导后仍是自身。</p><p>因此，我们采用一种新的 <strong>归一化方法：Softmax</strong>。它利用 exp 函数进行计算，能够将权重矩阵归一化，使得每行之和为 1，且便于求导。经过 Softmax 处理后，我们得到了归一化后的概率矩阵。此时，广东人点银鱼炒蛋的概率为 0.36，点石斑鱼的概率为 0.33，排名依然靠前。同时，不同行之间也可以比较了，例如四川人点水煮鱼的概率为 36%，广东人点小炒肉的概率为 19%。这样数据更规整，易于处理。</p><p>归一化得到的是点每道菜的概率。接下来，我们可以用这个概率计算每个维度的数学期望。以山东人为例，他点四道菜的概率分别为 22%、22%、21%、32%。如果要评价餐厅的“海鲜”维度，就计算点石斑鱼的概率乘以石斑鱼的海鲜分数，加上点银鱼炒蛋的概率乘以其海鲜分数，以此类推。这就是数学期望：根据点菜概率，对餐厅各个维度进行加权评价。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/2b839e939246fyy3cfb48329f44640d4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/2b839e939246fyy3cfb48329f44640d4.png" alt="图片"></a></p><p>整个过程可总结为：两个矩阵做内积，得到初始权重矩阵；用 Softmax 归一化，得到真实概率矩阵；再用该概率矩阵与客观评价矩阵相乘，得到每个人对餐厅各维度的评分（数学期望）。这样得到的评分融入了个人喜好，不再是完全客观的。例如，虽然只有两道菜提供海鲜，但广东人对海鲜的评分可能依然很高；三道菜提供辣度，但大家对辣度的评分未必都高。 <strong>这说明，加入注意力机制后，评分发生了主观性变化，这是 Attention 与以往多层感知机的根本区别。</strong></p><p>在自然语言处理中，我们可以计算每个词与之前所有词的注意力。例如，在“我口渴了，我要……”这样的语料中，“喝水”与“口渴”之间的注意力权重会远高于其他词对。这就是 Attention 在训练时的直观理解： <strong>注意力即 A 对 B 的关注程度。</strong></p><p>对应到论文中的 Q、K、V：查询（Q）即食客，键（K）即菜单，值（V）即客观评价。计算过程是：Q 与 K 做内积，再经 Softmax 得到概率矩阵，最后与 V 相乘得到 Attention 输出。整个过程与餐厅打分类似，并不复杂。</p><p>可能有人会问：自然语言处理中，词是如何表示的呢？在训练时，左边的“菜名”对应一个个单词（Token），如“口渴”“喝水”。右边的维度则通过词嵌入学习得到，具体如何学习，推荐阅读极客时间上黄佳老师关于自然语言处理或 ChatGPT 的专栏，其中有详细说明。由于直播时间有限，这里只聚焦关键概念。</p><p>至此，Attention 的主要内容就讲完了。它的计算就是矩阵乘、Softmax、再矩阵乘，结构简单。关键在于理解为什么这样计算。</p><p>在实际中，我们常用 <strong>多头注意力（MHA）</strong>。Attention 有很多变种，如 Flash Attention、GQA、Linear Attention 等，但核心计算未变。当维度较多时，我们可以分组处理，例如将味道、气味、辣度等拆分成不同组，并行计算注意力，这就是多头注意力。</p><h2 id="transformer-的整体结构" tabindex="-1"><strong>Transformer 的整体结构</strong> <a class="header-anchor" href="#transformer-的整体结构" aria-label="Permalink to &quot;**Transformer 的整体结构**&quot;">​</a></h2><p>接下来我们看 Transformer 的整体结构。如图所示，输入经过词嵌入转换为向量，进入多头注意力模块。之后加上残差连接与层归一化，再经过前馈网络（即多层感知机），最后输出。残差连接的形式是 y = f(x) + x，用于缓解梯度消失和爆炸；层归一化也用于提高训练稳定性。前馈网络是全连接层，参数量很大，是大模型的主要部分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/7f40370c3bfa7b83d74864yy3115eaf5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BC%96%E7%A8%8B%E9%AB%98%E6%89%8B%E5%BF%85%E5%AD%A6%E7%9A%84%E5%86%85%E5%AD%98%E7%9F%A5%E8%AF%86/images/935649/7f40370c3bfa7b83d74864yy3115eaf5.png" alt="图片"></a></p><p>输出层经过 Softmax 或线性层后，给出每个候选词的概率。例如，输入“我口渴了”，模型可能输出“喝水”“吃饭”“睡觉”等，其中“喝水”的概率最高，因此模型生成“喝水”。这就是注意力机制在生成式任务中的作用。</p><p>自然语言词汇量巨大，每个词与其他词都有注意力权重，因此需要大量参数和语料来训练。这就是为什么大模型需要万亿参数和数十 TB 的语料。参数量不足时，模型表现往往一般。</p><p>我在消费级显卡上做过实验，用《哈利·波特与火焰杯》的几万词文本训练一个小模型，生成效果不错。大家也可以在自有显卡或云平台（如 AutoDL）上尝试，包括使用摩尔线程的卡。我在摩尔线程的 AI Book（32G 显存）上训练过，结果在我的微信朋友圈分享过，效果尚可。</p><p>今天关于 Transformer 和 Attention 的核心内容就这些。结合上节课，我们做一个总结。</p><p>我的专栏《编程高手必学的内存知识》其实永不过时。例如在做 GPU 编译器时，NVCC 生成的 fitbit 仍是 ELF 结构，涉及链接器等知识；GPU 存储体系中的 SRAM 与电路结构，在专栏中也有涉及。学习这些后，再看 GPU 编程，会发现很多知识是从 CPU 迁移而来的。</p><p>这正是我们这两次直播想传达的信息：不要认为 AI 时代只需学习 AI 相关知识。以前在 CPU 上投入的学习并不会白费。包括大学里的线性代数、概率论等基础课程，你可能没想到它们会有今天的应用。我讲的内容，其实都未超出大学范围——计算机体系结构、组成原理、概率论、线性代数等。如果基础扎实，这些内容很容易理解。</p><p>未来如果有机会，我可以讲解模型训练、神经网络等内容，那将涉及微积分、梯度下降、矩阵求导等，本质上仍是数学与基础的延伸。所以，我想强调的是：不要被专有名词吓倒。AI 时代开启后，AI Infra 岗位需求旺盛，大厂招聘薪资也很高。 <strong>常有人问我能否转型 AI，我认为只要基础扎实，完全可行。但指望 21 天速成或短期培训就能获得高薪，绝对不现实。</strong></p><p>关键在于扎实的基础：手算梯度下降、理解模型中的数学公式、掌握泰勒展开、精度估计等。这些能力在训练前就能帮助你在纸上进行预估。要跟上这个时代，重要的不是读了多少 GPU 的书、记了多少模型，而是微积分、线性代数、概率论、数据结构、操作系统、编译器、体系结构这些基础知识。课本内容至今仍未过时，在 GPU 时代反而更加重要。</p><p>GPU 是否是 AI 计算的唯一范式？不一定。目前它是对的，但十年后未必。然而，这些基础知识——包括我推荐的《从零开始写 Linux 内核》和《编程高手必学的内存知识》——现在不过时，十年后也不会过时。</p><p>今天的内容就到这里。总结来说，希望大家在 AI 时代不要迷失本心，夯实基础，找到属于自己的未来。周末愉快，感谢聆听，再见！</p>',44)])])}const g=e(o,[["render",s]]);export{l as __pageData,g as default};
